-- READ-ONLY query template. Execute separately in old_weewx and weewx_WH1080.
-- It emits SHA-256 of each timestamp/value sequence within each of the 44 exact open intervals.
-- Compare only when expected and actual serialized byte lengths match (guards GROUP_CONCAT truncation).
-- Fields: usUnits, interval, outTemp, outHumidity, rain, rainRate, windSpeed, windDir, windGust, barometer.
-- This comparison tests copy concordance; it does not prove source truth or cleaning intent.

SELECT gap_id, COUNT(*) AS source_rows, SHA2(GROUP_CONCAT(usUnits_s ORDER BY dateTime SEPARATOR '\n'),256) AS usUnits_sha256, SUM(OCTET_LENGTH(usUnits_s))+COUNT(*)-1 AS usUnits_bytes_expected, LENGTH(GROUP_CONCAT(usUnits_s ORDER BY dateTime SEPARATOR '\n')) AS usUnits_bytes_actual, SHA2(GROUP_CONCAT(interval_s ORDER BY dateTime SEPARATOR '\n'),256) AS interval_sha256, SUM(OCTET_LENGTH(interval_s))+COUNT(*)-1 AS interval_bytes_expected, LENGTH(GROUP_CONCAT(interval_s ORDER BY dateTime SEPARATOR '\n')) AS interval_bytes_actual, SHA2(GROUP_CONCAT(outTemp_s ORDER BY dateTime SEPARATOR '\n'),256) AS outTemp_sha256, SUM(OCTET_LENGTH(outTemp_s))+COUNT(*)-1 AS outTemp_bytes_expected, LENGTH(GROUP_CONCAT(outTemp_s ORDER BY dateTime SEPARATOR '\n')) AS outTemp_bytes_actual, SHA2(GROUP_CONCAT(outHumidity_s ORDER BY dateTime SEPARATOR '\n'),256) AS outHumidity_sha256, SUM(OCTET_LENGTH(outHumidity_s))+COUNT(*)-1 AS outHumidity_bytes_expected, LENGTH(GROUP_CONCAT(outHumidity_s ORDER BY dateTime SEPARATOR '\n')) AS outHumidity_bytes_actual, SHA2(GROUP_CONCAT(rain_s ORDER BY dateTime SEPARATOR '\n'),256) AS rain_sha256, SUM(OCTET_LENGTH(rain_s))+COUNT(*)-1 AS rain_bytes_expected, LENGTH(GROUP_CONCAT(rain_s ORDER BY dateTime SEPARATOR '\n')) AS rain_bytes_actual, SHA2(GROUP_CONCAT(rainRate_s ORDER BY dateTime SEPARATOR '\n'),256) AS rainRate_sha256, SUM(OCTET_LENGTH(rainRate_s))+COUNT(*)-1 AS rainRate_bytes_expected, LENGTH(GROUP_CONCAT(rainRate_s ORDER BY dateTime SEPARATOR '\n')) AS rainRate_bytes_actual, SHA2(GROUP_CONCAT(windSpeed_s ORDER BY dateTime SEPARATOR '\n'),256) AS windSpeed_sha256, SUM(OCTET_LENGTH(windSpeed_s))+COUNT(*)-1 AS windSpeed_bytes_expected, LENGTH(GROUP_CONCAT(windSpeed_s ORDER BY dateTime SEPARATOR '\n')) AS windSpeed_bytes_actual, SHA2(GROUP_CONCAT(windDir_s ORDER BY dateTime SEPARATOR '\n'),256) AS windDir_sha256, SUM(OCTET_LENGTH(windDir_s))+COUNT(*)-1 AS windDir_bytes_expected, LENGTH(GROUP_CONCAT(windDir_s ORDER BY dateTime SEPARATOR '\n')) AS windDir_bytes_actual, SHA2(GROUP_CONCAT(windGust_s ORDER BY dateTime SEPARATOR '\n'),256) AS windGust_sha256, SUM(OCTET_LENGTH(windGust_s))+COUNT(*)-1 AS windGust_bytes_expected, LENGTH(GROUP_CONCAT(windGust_s ORDER BY dateTime SEPARATOR '\n')) AS windGust_bytes_actual, SHA2(GROUP_CONCAT(barometer_s ORDER BY dateTime SEPARATOR '\n'),256) AS barometer_sha256, SUM(OCTET_LENGTH(barometer_s))+COUNT(*)-1 AS barometer_bytes_expected, LENGTH(GROUP_CONCAT(barometer_s ORDER BY dateTime SEPARATOR '\n')) AS barometer_bytes_actual FROM (
